B=http://localhost:3000/api/v1; L=raw9.log
req(){ m=$1; p=$2; d=$3; echo "### $m $p $d" >>$L; if [ -n "$d" ]; then r=$(curl -s -w '\n[HTTP %{http_code}]' -X $m "$B$p" -H "Authorization: Bearer $T" ${DN:+-H "X-Debug-Now: $DN"} -H 'Content-Type: application/json' -d "$d"); else r=$(curl -s -w '\n[HTTP %{http_code}]' -X $m "$B$p" -H "Authorization: Bearer $T" ${DN:+-H "X-Debug-Now: $DN"}); fi; echo "$r" >>$L; echo >>$L; echo "$r"; }
reg(){ echo "## ===== $1 =====" >>$L; R=$(curl -s -X POST $B/auth/register -H 'Content-Type: application/json' $2 -d "{\"username\":\"$1\",\"password\":\"${TEST_PW:-$(cat /workspace/.kaoyan_testpw)}\"}"); echo "### register $1 $2" >>$L; echo "$R" | sed 's/"access_token":"[^"]*"/"access_token":"…"/;s/"refresh_token":"[^"]*"/"refresh_token":"…"/' >>$L; T=$(echo "$R"|jq -r .access_token); echo "$R"|jq -c '.user.timezone // .timezone'; }
